function secondHighest(numbers: number[]): number | undefined {
  let highest = -Infinity;
  let second = -Infinity;

  for (const n of numbers) {
    if (n > highest) {
      second = highest;
      highest = n;
    } else if (n < highest && n > second) {
      second = n;
    }
  }

  return second === -Infinity ? undefined : second;
}

